        "manzil_desc_al_falaq": [.indonesian: "Seek refuge with the Lord of daybreak from the evil of creation, darkness, sorcery, and envy.", .english: "Seek refuge with the Lord of daybreak from the evil of creation, darkness, sorcery, and envy.", .malay: "Seek refuge with the Lord of daybreak from the evil of creation, darkness, sorcery, and envy."],
        "manzil_desc_al_hasyr": [.indonesian: "If this Quran were sent upon a mountain, it would crumble — He is Allah, the Creator, the Bestower of Forms, the Most Beautiful Names.", .english: "If this Quran were sent upon a mountain, it would crumble — He is Allah, the Creator, the Bestower of Forms, the Most Beautiful Names.", .malay: "If this Quran were sent upon a mountain, it would crumble — He is Allah, the Creator, the Bestower of Forms, the Most Beautiful Names."],
        "manzil_desc_al_ikhlas": [.indonesian: "The essence of Tawheed — He is Allah, the One, the Eternal Refuge, who begets not nor is begotten.", .english: "The essence of Tawheed — He is Allah, the One, the Eternal Refuge, who begets not nor is begotten.", .malay: "The essence of Tawheed — He is Allah, the One, the Eternal Refuge, who begets not nor is begotten."],
        "manzil_desc_al_isra": [.indonesian: "Call upon Allah or Ar-Rahman — to Him belong the Most Beautiful Names. Praise be to Him who has no son nor partner.", .english: "Call upon Allah or Ar-Rahman — to Him belong the Most Beautiful Names. Praise be to Him who has no son nor partner.", .malay: "Call upon Allah or Ar-Rahman — to Him belong the Most Beautiful Names. Praise be to Him who has no son nor partner."],
        "manzil_desc_al_jinn": [.indonesian: "A group of jinn heard the Quran, believed, and declared their faith — our Lord has no spouse or child.", .english: "A group of jinn heard the Quran, believed, and declared their faith — our Lord has no spouse or child.", .malay: "A group of jinn heard the Quran, believed, and declared their faith — our Lord has no spouse or child."],
        "manzil_desc_al_kafirun": [.indonesian: "A declaration of disavowal from disbelief — to you your religion, to me mine.", .english: "A declaration of disavowal from disbelief — to you your religion, to me mine.", .malay: "A declaration of disavowal from disbelief — to you your religion, to me mine."],
        "manzil_desc_al_muminun": [.indonesian: "Were you created without purpose? Exalted is Allah, the True King — seek His forgiveness and mercy.", .english: "Were you created without purpose? Exalted is Allah, the True King — seek His forgiveness and mercy.", .malay: "Were you created without purpose? Exalted is Allah, the True King — seek His forgiveness and mercy."],
        "manzil_desc_ali_imran_18": [.indonesian: "Allah testifies that there is no deity but Him — the Almighty, the All-Wise.", .english: "Allah testifies that there is no deity but Him — the Almighty, the All-Wise.", .malay: "Allah testifies that there is no deity but Him — the Almighty, the All-Wise."],
        "manzil_desc_ali_imran_26": [.indonesian: "Say: O Allah, Owner of sovereignty — You give honour and power to whom You will.", .english: "Say: O Allah, Owner of sovereignty — You give honour and power to whom You will.", .malay: "Say: O Allah, Owner of sovereignty — You give honour and power to whom You will."],
        "manzil_desc_ali_imran_27": [.indonesian: "You cause the night to enter the day and bring the living from the dead — You provide for whom You will without measure.", .english: "You cause the night to enter the day and bring the living from the dead — You provide for whom You will without measure.", .malay: "You cause the night to enter the day and bring the living from the dead — You provide for whom You will without measure."],
        "manzil_desc_an_nas": [.indonesian: "Seek refuge with the Lord of mankind, the King of mankind, from the whisperer who withdraws.", .english: "Seek refuge with the Lord of mankind, the King of mankind, from the whisperer who withdraws.", .malay: "Seek refuge with the Lord of mankind, the King of mankind, from the whisperer who withdraws."],
        "manzil_desc_ar_rahman": [.indonesian: "O assembly of jinn and men — none can escape Allah's authority. Which of your Lord's favours will you deny?", .english: "O assembly of jinn and men — none can escape Allah's authority. Which of your Lord's favours will you deny?", .malay: "O assembly of jinn and men — none can escape Allah's authority. Which of your Lord's favours will you deny?"],
        "manzil_desc_ash_shaffat": [.indonesian: "By the angels ranged in rows — your God is One, Lord of the heavens and the earth.", .english: "By the angels ranged in rows — your God is One, Lord of the heavens and the earth.", .malay: "By the angels ranged in rows — your God is One, Lord of the heavens and the earth."],
        "manzil_desc_ayat_kursi": [.indonesian: "The greatest verse in the Quran — a fortress of protection. Whoever recites it at night remains under Allah's protection until morning.", .english: "The greatest verse in the Quran — a fortress of protection. Whoever recites it at night remains under Allah's protection until morning.", .malay: "The greatest verse in the Quran — a fortress of protection. Whoever recites it at night remains under Allah's protection until morning."],
        "manzil_desc_baqarah_1": [.indonesian: "Continue with the opening of Al-Baqarah — guidance for the God-conscious and the path to success.", .english: "Continue with the opening of Al-Baqarah — guidance for the God-conscious and the path to success.", .malay: "Continue with the opening of Al-Baqarah — guidance for the God-conscious and the path to success."],
        "manzil_desc_baqarah_163": [.indonesian: "Your God is One — there is no deity but Him, the Most Gracious, the Most Merciful.", .english: "Your God is One — there is no deity but Him, the Most Gracious, the Most Merciful.", .malay: "Your God is One — there is no deity but Him, the Most Gracious, the Most Merciful."],
        "manzil_desc_baqarah_256": [.indonesian: "There is no compulsion in religion — truth has become clear from falsehood.", .english: "There is no compulsion in religion — truth has become clear from falsehood.", .malay: "There is no compulsion in religion — truth has become clear from falsehood."],
        "manzil_desc_baqarah_257": [.indonesian: "Allah is the Protector of the believers, bringing them from darkness into light.", .english: "Allah is the Protector of the believers, bringing them from darkness into light.", .malay: "Allah is the Protector of the believers, bringing them from darkness into light."],
        "manzil_desc_baqarah_284": [.indonesian: "To Allah belongs all that is in the heavens and earth — He will call you to account for what is in your hearts.", .english: "To Allah belongs all that is in the heavens and earth — He will call you to account for what is in your hearts.", .malay: "To Allah belongs all that is in the heavens and earth — He will call you to account for what is in your hearts."],
        "manzil_desc_baqarah_285": [.indonesian: "The Messenger and believers have faith in what was revealed — we hear and we obey, seeking Your forgiveness.", .english: "The Messenger and believers have faith in what was revealed — we hear and we obey, seeking Your forgiveness.", .malay: "The Messenger and believers have faith in what was revealed — we hear and we obey, seeking Your forgiveness."],
        "manzil_desc_baqarah_286": [.indonesian: "Allah does not burden a soul beyond its capacity — the closing supplication of Al-Baqarah for forgiveness and help.", .english: "Allah does not burden a soul beyond its capacity — the closing supplication of Al-Baqarah for forgiveness and help.", .malay: "Allah does not burden a soul beyond its capacity — the closing supplication of Al-Baqarah for forgiveness and help."],
        "manzil_desc_fatihah": [.indonesian: "Begin Manzil with Al-Fatihah — the greatest surah, recited in every rakah. A cure and protection.", .english: "Begin Manzil with Al-Fatihah — the greatest surah, recited in every rakah. A cure and protection.", .malay: "Begin Manzil with Al-Fatihah — the greatest surah, recited in every rakah. A cure and protection."],
        "manzil_fami_desc": [.indonesian: "A mnemonic phrase meaning \"My mouth longs to recite (the Quran)\". The 7 letters — ف م ي ب ش و ق — are the first letters of the surah that begins each of the 7 Manzils: Al-Fatihah, Al-Ma'idah, Yunus, Al-Isra', Ash-Shu'ara, Ash-Shaffat, and Qaf.", .english: "A mnemonic phrase meaning \"My mouth longs to recite (the Quran)\". The 7 letters — ف م ي ب ش و ق — are the first letters of the surah that begins each of the 7 Manzils: Al-Fatihah, Al-Ma'idah, Yunus, Al-Isra', Ash-Shu'ara, Ash-Shaffat, and Qaf.", .malay: "A mnemonic phrase meaning \"My mouth longs to recite (the Quran)\". The 7 letters — ف م ي ب ش و ق — are the first letters of the surah that begins each of the 7 Manzils: Al-Fatihah, Al-Ma'idah, Yunus, Al-Isra', Ash-Shu'ara, Ash-Shaffat, and Qaf."],
        "manzil_fami_label": [.indonesian: "Fami bi Shawqin (فَمِي بِشَوْقٍ)", .english: "Fami bi Shawqin (فَمِي بِشَوْقٍ)", .malay: "Fami bi Shawqin (فَمِي بِشَوْقٍ)"],
        "manzil_header_body": [.indonesian: "A collection of selected verses for protection from sihr, jinn, and harm, compiled by scholars in the Indian subcontinent.", .english: "A collection of selected verses for protection from sihr, jinn, and harm, compiled by scholars in the Indian subcontinent.", .malay: "A collection of selected verses for protection from sihr, jinn, and harm, compiled by scholars in the Indian subcontinent."],
        "manzil_header_title": [.indonesian: "Protection from the Quran", .english: "Protection from the Quran", .malay: "Protection from the Quran"],
        "manzil_how_body": [.indonesian: "Each day, recite one Manzil in sequence from Monday to Sunday, completing the entire Quran in one week. You may recite it in one sitting or spread it across multiple sessions during the day (e.g. after Fajr, Zuhr, Asr, Maghrib, and Isya').\\n\\nTo begin, start with Manzil 1 (Juz 1–6) and proceed to the next Manzil each day. Consistency is key — even if you cannot complete a full Manzil in a day, try to at least read a portion and continue the next day.", .english: "Each day, recite one Manzil in sequence from Monday to Sunday, completing the entire Quran in one week. You may recite it in one sitting or spread it across multiple sessions during the day (e.g. after Fajr, Zuhr, Asr, Maghrib, and Isya').\\n\\nTo begin, start with Manzil 1 (Juz 1–6) and proceed to the next Manzil each day. Consistency is key — even if you cannot complete a full Manzil in a day, try to at least read a portion and continue the next day.", .malay: "Each day, recite one Manzil in sequence from Monday to Sunday, completing the entire Quran in one week. You may recite it in one sitting or spread it across multiple sessions during the day (e.g. after Fajr, Zuhr, Asr, Maghrib, and Isya').\\n\\nTo begin, start with Manzil 1 (Juz 1–6) and proceed to the next Manzil each day. Consistency is key — even if you cannot complete a full Manzil in a day, try to at least read a portion and continue the next day."],
        "manzil_how_title": [.indonesian: "How to Practice", .english: "How to Practice", .malay: "How to Practice"],
        "manzil_info_definition": [.indonesian: "Manzil (Arabic: منزل) is a system for dividing the recitation of the Quran to facilitate completing (khatam) the Quran over seven days (one week). This tradition is widely practiced in South Asian Muslim communities and has been popularized by scholars such as Shah Waliullah al-Dehlawi.\\n\\nNote: \"Manzil\" here refers to the 7-part Quran division for khatam, and is different from the protection verses (Manzil ruqyah) compiled by Maulana Zakariyya Kandhlawi. This section in the app covers the protection verses.", .english: "Manzil (Arabic: منزل) is a system for dividing the recitation of the Quran to facilitate completing (khatam) the Quran over seven days (one week). This tradition is widely practiced in South Asian Muslim communities and has been popularized by scholars such as Shah Waliullah al-Dehlawi.\\n\\nNote: \"Manzil\" here refers to the 7-part Quran division for khatam, and is different from the protection verses (Manzil ruqyah) compiled by Maulana Zakariyya Kandhlawi. This section in the app covers the protection verses.", .malay: "Manzil (Arabic: منزل) is a system for dividing the recitation of the Quran to facilitate completing (khatam) the Quran over seven days (one week). This tradition is widely practiced in South Asian Muslim communities and has been popularized by scholars such as Shah Waliullah al-Dehlawi.\\n\\nNote: \"Manzil\" here refers to the 7-part Quran division for khatam, and is different from the protection verses (Manzil ruqyah) compiled by Maulana Zakariyya Kandhlawi. This section in the app covers the protection verses."],
        "manzil_info_subtitle": [.indonesian: "Definition, 7-day division & practice guide", .english: "Definition, 7-day division & practice guide", .malay: "Definition, 7-day division & practice guide"],
