        "night_first_third_body": [.indonesian: "Malam telah tiba. Istirahatlah dengan cukup, Kīmi akan mengingatkanmu saat sepertiga akhir malam tiba.", .english: "Malam telah tiba. Istirahatlah dengan cukup, Kīmi akan mengingatkanmu saat sepertiga akhir malam tiba.", .malay: "Malam telah tiba. Berehatlah secukupnya, Kīmi akan mengingatkanmu apabila sepertiga akhir malam tiba."],
        "night_first_third_title": [.indonesian: "Kīmi Mengingatkan", .english: "Kīmi Mengingatkan", .malay: "Kīmi Mengingatkan"],
