        "night_last_third_body": [.indonesian: "Sepertiga akhir malam telah tiba. Kīmi mengajakmu bangun dan mendekat kepada Allah.", .english: "Sepertiga akhir malam telah tiba. Kīmi mengajakmu bangun dan mendekat kepada Allah.", .malay: "Sepertiga akhir malam telah tiba. Kīmi mengajakmu bangun dan mendekatkan diri kepada Allah."],
        "night_last_third_title": [.indonesian: "Sepertiga Akhir Telah Tiba", .english: "Sepertiga Akhir Telah Tiba", .malay: "Sepertiga Akhir Telah Tiba"],
        "night_midnight_body": [.indonesian: "Sudah tengah malam. Jika belum tidur, jangan lupa menunaikan Witir sebelum beristirahat.", .english: "Sudah tengah malam. Jika belum tidur, jangan lupa menunaikan Witir sebelum beristirahat.", .malay: "Sudah tengah malam. Jika belum tidur, jangan lupa menunaikan solat Witir sebelum berehat."],
